// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
// [slug, name, one-line definition, category, written in this locale (1) or English fallback (0)], sorted by name.
export const GLOSSARY_INDEX = Object.freeze({"locale":"en","terms":[["active-addresses","Active addresses","Active addresses are the number of unique blockchain addresses that sent or received a transaction during a given period, often counted per day.","onchain",1],["address-poisoning","Address poisoning","Address poisoning is a scam where an attacker sends a tiny or zero-value transfer from an address that looks like one you use, hoping you later copy that fake address from your transaction history.","wallets-security",1],["airdrop","Airdrop","An airdrop is a distribution of free tokens to wallet addresses or exchange users, usually to reward early users, decentralize ownership or promote a new project.","basics",1],["algorithmic-stablecoin","Algorithmic stablecoin","An algorithmic stablecoin is a stablecoin that tries to hold its peg mainly through code-driven supply changes and incentives rather than full reserves of cash or collateral.","stablecoins",1],["all-time-high","All-time high (ATH)","An all-time high (ATH) is the highest price an asset has ever reached in its trading history, and the opposite, the lowest price ever, is called an all-time low (ATL).","basics",1],["altcoin","Altcoin","An altcoin is any cryptocurrency other than Bitcoin, a broad category that includes Ether, Solana, stablecoins, exchange tokens and memecoins.","basics",1],["aml","AML (anti-money laundering)","AML (anti-money laundering) is the set of laws and internal controls that financial firms, including crypto exchanges, use to detect and prevent illegal funds from entering the system.","regulation",1],["anti-phishing-code","Anti-phishing code","An anti-phishing code is a personal word or phrase you set in your exchange account that the exchange includes in its genuine emails, so you can spot fake messages that do not contain it.","wallets-security",1],["apr-vs-apy","APR vs APY","APR is the simple annual rate of return or interest without compounding, while APY includes the effect of reinvesting earnings, so APY is higher than APR whenever returns compound.","defi",1],["arbitrage","Arbitrage","Arbitrage is buying an asset where it is cheaper and selling it where it is more expensive at the same time, to profit from a price difference between markets.","trading",1],["auto-deleveraging","Auto-deleveraging (ADL)","Auto-deleveraging (ADL) is a last-resort mechanism where an exchange automatically reduces profitable opposing positions to cover a liquidation that the market and insurance fund cannot absorb.","derivatives",1],["amm","Automated market maker (AMM)","An automated market maker (AMM) is a type of DEX that prices trades with a mathematical formula based on the tokens held in a liquidity pool, instead of matching buyers and sellers in an order book.","defi",1],["bear-market","Bear market","A bear market is a sustained period of falling prices and pessimistic sentiment, commonly described as a decline of 20 percent or more from a recent high.","basics",1],["bid-ask-spread","Bid-ask spread","The bid-ask spread is the difference between the highest price a buyer is willing to pay (the bid) and the lowest price a seller is willing to accept (the ask) for an asset at a given moment.","trading",1],["bitcoin","Bitcoin (BTC)","Bitcoin (BTC) is the first cryptocurrency, a decentralized digital money with a hard cap of 21 million coins that runs on its own proof-of-work blockchain.","basics",1],["bitcoin-halving","Bitcoin halving","A Bitcoin halving is a pre-programmed event, roughly every four years, that cuts the number of new bitcoins paid to miners for each block by 50 percent.","basics",1],["block-confirmations","Block confirmations","Block confirmations are the number of blocks added to a blockchain since the block that includes your transaction, and exchanges wait for a set number before crediting a deposit.","wallets-security",1],["block-explorer","Block explorer","A block explorer is a website or app that lets you search a blockchain's public records, including transactions, addresses, blocks and token transfers.","onchain",1],["blockchain","Blockchain","A blockchain is a shared digital ledger, copied across many computers, where transactions are grouped into blocks that are linked in order and are extremely hard to change after the fact.","basics",1],["oracle","Blockchain oracle","A blockchain oracle is a service that brings outside data, most often asset prices, onto a blockchain so smart contracts can use it for actions like liquidations, settlements and swaps.","defi",1],["bull-market","Bull market","A bull market is a sustained period when prices rise broadly and investor confidence is high, commonly described as a gain of 20 percent or more from a recent low.","basics",1],["candlestick-chart","Candlestick chart","A candlestick chart is a price chart where each candle shows the open, high, low and close price of an asset over one time period.","trading",1],["cbdc","CBDC (central bank digital currency)","A CBDC (central bank digital currency) is a digital form of a country's official money issued and backed directly by its central bank, not by a private company.","stablecoins",1],["centralized-exchange","Centralized exchange (CEX)","A centralized exchange (CEX) is a company-run trading platform where you deposit funds into an account and trade crypto through the exchange's order book, with the company holding custody of your assets.","trading",1],["circulating-supply","Circulating supply","Circulating supply is the number of coins or tokens that are publicly available and moving in the market right now, excluding locked, reserved or burned tokens.","basics",1],["coin-vs-token","Coin vs token","A coin is the native asset of its own blockchain, such as BTC or ETH, while a token is an asset created on top of an existing blockchain using a smart contract, such as USDT on Ethereum.","basics",1],["coin-margined-futures","Coin-margined (inverse) futures","Coin-margined (inverse) futures are futures contracts where margin and profit or loss are in the underlying coin, such as BTC, instead of a stablecoin.","derivatives",1],["cold-wallet","Cold wallet (cold storage)","A cold wallet is a way of storing crypto where the private keys are generated and kept offline, away from internet-connected devices, so remote attackers cannot reach them.","wallets-security",1],["instant-convert","Convert (instant swap)","Convert is an exchange feature that swaps one coin for another at a quoted price in one click, without using the order book directly.","exchange-features",1],["copy-trading","Copy trading","Copy trading is an exchange feature that automatically mirrors another trader's positions in your own account, in proportion to the amount you allocate.","exchange-features",1],["cross-margin","Cross margin","Cross margin is a margin mode where all your open positions share the available balance in your account as collateral, so profits and spare funds can absorb losses before liquidation.","derivatives",1],["cross-chain-bridge","Cross-chain bridge","A cross-chain bridge is a protocol that moves tokens or messages between two blockchains, usually by locking or burning assets on one chain and releasing or minting matching assets on the other.","defi",1],["crypto-earn","Crypto Earn (savings products)","Crypto Earn refers to exchange savings products that pay you a yield for depositing crypto, either flexible with withdrawal anytime or locked for a fixed term.","exchange-features",1],["mining","Crypto mining","Crypto mining is the process of using specialised computers to secure a proof-of-work blockchain by adding new blocks, in exchange for newly issued coins and transaction fees.","basics",1],["options","Crypto options","Crypto options are contracts that give the buyer the right, but not the obligation, to buy (call) or sell (put) a cryptocurrency at a set strike price on or before a set expiry date.","derivatives",1],["crypto-wallet","Crypto wallet","A crypto wallet is software or a device that stores the private keys controlling your cryptocurrency and lets you send, receive and manage it on the blockchain.","wallets-security",1],["crypto-backed-stablecoin","Crypto-backed stablecoin","A crypto-backed stablecoin is a stablecoin issued against crypto collateral locked in smart contracts, usually worth more than the coins created, so the token can stay near 1 USD.","stablecoins",1],["cryptocurrency","Cryptocurrency","A cryptocurrency is a digital asset that is issued and transferred on a blockchain, secured by cryptography instead of a bank or central authority.","basics",1],["custodial-wallet","Custodial wallet","A custodial wallet is a crypto wallet where a third party, usually an exchange or app, holds the private keys and controls the funds on your behalf.","wallets-security",1],["dao","DAO (decentralized autonomous organization)","A DAO, or decentralized autonomous organization, is a community that makes decisions and manages a shared treasury through token-holder voting and smart contracts instead of a traditional management structure.","defi",1],["dex","Decentralized exchange (DEX)","A decentralized exchange (DEX) is a trading platform that runs on smart contracts, letting you swap tokens directly from your own wallet without depositing funds with a company.","defi",1],["defi","DeFi (decentralized finance)","DeFi, short for decentralized finance, is a set of financial services such as trading, lending and earning yield that run on public blockchains through smart contracts instead of through banks or exchanges.","defi",1],["defi-lending","DeFi lending","DeFi lending is borrowing and lending crypto through smart contracts, where lenders earn interest from a shared pool and borrowers must lock more collateral than they borrow.","defi",1],["delisting","Delisting","Delisting is when an exchange removes a token or trading pair, ending trading and usually setting a deadline to withdraw the remaining balances.","exchange-features",1],["delivery-futures","Delivery (quarterly) futures","Delivery futures are crypto futures contracts with a fixed expiry date, such as a weekly or quarterly contract, that settle at a set price when they expire.","derivatives",1],["demo-trading","Demo trading","Demo trading is practising on an exchange with virtual funds in a simulated account, so you can learn order types, leverage and futures mechanics without risking real money.","exchange-features",1],["depeg","Depeg","A depeg is when a stablecoin or pegged token trades meaningfully away from the value it is designed to track, such as a dollar stablecoin falling below 1 USD.","stablecoins",1],["blockchain-network","Deposit network (chain selection)","A deposit network is the blockchain you choose to move a coin or token over when you deposit to or withdraw from an exchange, and the sending and receiving sides must use the same one.","wallets-security",1],["dollar-cost-averaging","Dollar-cost averaging (DCA)","Dollar-cost averaging (DCA) is a strategy of buying a fixed amount of an asset at regular intervals, regardless of price, to spread your entry over time.","trading",1],["dual-investment","Dual investment","Dual investment is a structured exchange product where you earn a fixed yield but may be paid back in a different coin depending on whether the price ends above or below a target price on settlement.","exchange-features",1],["ethereum","Ethereum (ETH)","Ethereum is a programmable blockchain that runs smart contracts, and Ether (ETH) is its native coin used to pay gas fees and to stake for network security.","basics",1],["exchange-netflow","Exchange inflows and outflows","Exchange inflows and outflows measure how much of a coin moves onto and off centralized exchanges, and netflow is inflows minus outflows over a period.","onchain",1],["fear-and-greed-index","Fear and Greed Index","The Fear and Greed Index is a sentiment gauge that combines market data such as volatility, momentum and social activity into a single score from 0 (extreme fear) to 100 (extreme greed).","onchain",1],["fiat-on-ramp","Fiat on-ramp","A fiat on-ramp is any service that turns government money like dollars or euros into crypto, such as a bank transfer to an exchange, a card purchase or a P2P trade.","regulation",1],["flash-loan","Flash loan","A flash loan is an uncollateralized DeFi loan that must be borrowed and repaid, with a fee, within the same blockchain transaction, or the whole transaction is cancelled.","defi",1],["fomo","FOMO","FOMO, or fear of missing out, is the anxious urge to buy an asset after its price has already risen sharply, driven by the worry that others are profiting without you.","basics",1],["fud","FUD","FUD, short for fear, uncertainty and doubt, describes negative news, rumours or opinions that make people worried about an asset, whether the concerns are valid or not.","basics",1],["fully-diluted-valuation","Fully diluted valuation (FDV)","Fully diluted valuation (FDV) is a project's value if all of its tokens that will ever exist were already in circulation, calculated as the current price multiplied by the maximum or total supply.","basics",1],["funding-rate","Funding rate","A funding rate is a periodic payment between long and short traders that keeps a perpetual futures price close to the spot price.","derivatives",1],["funding-rate-arbitrage","Funding rate arbitrage","Funding rate arbitrage is a market-neutral strategy that collects funding payments by holding opposite positions, usually spot long and perpetual short, so price moves largely cancel out.","derivatives",1],["futures-basis","Futures basis","The futures basis is the difference between a futures contract's price and the spot price of the same asset, often expressed as an annualised percentage.","derivatives",1],["futures-contract","Futures contract","A futures contract is an agreement to buy or sell an asset at a set price in the future, which lets you trade price moves with margin and leverage without holding the asset itself.","derivatives",1],["gas-fee","Gas fee","A gas fee is the payment you make to a blockchain network to process a transaction or run a smart contract, paid in the chain's native coin such as ETH on Ethereum.","basics",1],["geo-restrictions","Geo-restrictions (restricted regions)","Geo-restrictions are the rules that stop an exchange or crypto service from offering some or all of its products to users in certain countries or regions.","regulation",1],["governance-token","Governance token","A governance token is a crypto token that gives holders the right to vote on a protocol's decisions, such as fee changes, upgrades and treasury spending, in proportion to the tokens they hold or delegate.","defi",1],["grid-trading-bot","Grid trading bot","A grid trading bot is an automated tool that places a ladder of buy and sell limit orders within a price range, profiting from repeated moves up and down.","exchange-features",1],["hardware-wallet","Hardware wallet","A hardware wallet is a small physical device that stores your private keys offline and signs transactions inside the device, so the keys never leave it even when it is plugged into a computer or phone.","wallets-security",1],["hash-rate","Hash rate","Hash rate is the total computing power that miners use to secure a proof-of-work blockchain, measured in hashes per second.","onchain",1],["hedging","Hedging","Hedging is opening a position that offsets the risk of another position, so that a loss on one is partly or fully balanced by a gain on the other.","derivatives",1],["hodl","HODL","HODL is crypto slang for holding an asset for the long term instead of selling during price drops, originating from a misspelling of \"hold\" in a 2013 Bitcoin forum post.","basics",1],["hot-wallet","Hot wallet","A hot wallet is a crypto wallet whose private keys are stored on a device connected to the internet, such as a phone app, browser extension or exchange system, which makes it convenient but more exposed to attacks.","wallets-security",1],["impermanent-loss","Impermanent loss","Impermanent loss is the shortfall a liquidity provider has compared with simply holding the same tokens, caused by the prices of the pooled tokens moving apart after the deposit.","defi",1],["index-price","Index price","The index price is a reference price for an asset calculated from a weighted average of spot prices on several major exchanges, used to anchor futures pricing.","derivatives",1],["initial-margin","Initial margin","Initial margin is the amount of collateral you must post to open a leveraged position, usually equal to the position value divided by your leverage.","derivatives",1],["insurance-fund","Insurance fund","An insurance fund is a reserve an exchange keeps to cover losses when liquidated positions cannot be closed at a price good enough to repay what they owe.","derivatives",1],["isolated-margin","Isolated margin","Isolated margin is a margin mode where each position has its own separate collateral, so a liquidation can only take the margin assigned to that position.","derivatives",1],["kyc","KYC (know your customer)","KYC (know your customer) is the identity check that regulated exchanges and financial firms run before letting you deposit, trade or withdraw, usually with an ID document and a selfie.","regulation",1],["last-price","Last traded price","The last traded price is the price at which the most recent trade on an order book was executed, and it is the price you usually see on charts and tickers.","derivatives",1],["launchpad","Launchpad (token sale)","A launchpad is a platform, often run by an exchange, where users can buy a new project's tokens in a sale before or as the tokens list for trading.","exchange-features",1],["launchpool","Launchpool","A Launchpool is an exchange program where you lock tokens you already hold, such as the exchange token or a stablecoin, for a set period to earn a new token before or around its listing.","exchange-features",1],["layer-1","Layer 1 (L1)","A layer 1 (L1) is a base blockchain that processes and finalises transactions on its own network with its own consensus and native coin, such as Bitcoin, Ethereum or Solana.","basics",1],["layer-2","Layer 2 (L2)","A layer 2 (L2) is a network built on top of a layer 1 blockchain that processes transactions off the main chain and posts the results back to it, giving lower fees while borrowing much of the L1's security.","basics",1],["leverage","Leverage","Leverage is using borrowed funds or margin to open a position larger than your own capital, which multiplies both profits and losses.","derivatives",1],["limit-order","Limit order","A limit order is an instruction to buy or sell only at a specific price or better, so a buy limit fills at your price or lower and a sell limit fills at your price or higher.","trading",1],["liquid-staking","Liquid staking","Liquid staking is a way to stake coins through a protocol that issues a tradable token, such as stETH, representing your staked position, so you earn staking rewards and can still use or sell the token.","defi",1],["liquidation","Liquidation","Liquidation is when an exchange forcibly closes your leveraged position because your margin has fallen below the maintenance margin requirement.","derivatives",1],["liquidation-price","Liquidation price","The liquidation price is the mark price at which your leveraged position will be forcibly closed because your margin would fall to the maintenance margin level.","derivatives",1],["liquidity","Liquidity","Liquidity is how easily you can buy or sell an asset quickly, in size, without moving its price much.","trading",1],["liquidity-pool","Liquidity pool","A liquidity pool is a smart contract holding two or more tokens that traders swap against on a DEX, funded by liquidity providers who earn a share of the trading fees.","defi",1],["long-and-short","Long and short positions","A long position profits when an asset's price rises, and a short position profits when its price falls.","derivatives",1],["long-short-ratio","Long/short ratio","The long/short ratio compares how many traders or how much position size on an exchange is long versus short on a futures market, as a gauge of sentiment.","derivatives",1],["maintenance-margin","Maintenance margin","Maintenance margin is the minimum collateral you must keep in a leveraged position; if your margin falls below it, the position is liquidated.","derivatives",1],["maker-taker-fees","Maker and taker fees","Maker and taker fees are the two trading fee rates an exchange charges: a maker fee when your order adds liquidity to the order book, and a usually higher taker fee when your order removes it.","trading",1],["margin-call","Margin call","A margin call is a warning that your collateral has fallen close to the minimum required for a leveraged position, so you need to add margin or reduce the position to avoid liquidation.","derivatives",1],["margin-trading","Margin trading","Margin trading is trading with funds borrowed from an exchange, using your own assets as collateral, so you can open larger positions or short-sell.","derivatives",1],["mark-price","Mark price","The mark price is a fair-value price an exchange uses to calculate unrealized profit and loss and to trigger liquidations, instead of the last traded price.","derivatives",1],["market-capitalization","Market capitalization","Market capitalization is the total value of a cryptocurrency's circulating coins, calculated as the current price multiplied by the circulating supply.","basics",1],["market-maker","Market maker","A market maker is a trader or firm that continuously places both buy and sell orders on a market, providing liquidity and earning from the spread between them.","trading",1],["market-order","Market order","A market order is an instruction to buy or sell immediately at the best price currently available in the order book, prioritising speed of execution over a specific price.","trading",1],["memecoin","Memecoin","A memecoin is a cryptocurrency inspired by an internet joke, animal or cultural trend, whose price is driven mainly by community attention rather than a product or cash flow.","basics",1],["memo-tag","Memo / destination tag","A memo or destination tag is an extra code attached to a transfer that tells an exchange which customer account should receive a deposit sent to a shared address.","wallets-security",1],["mempool","Mempool","The mempool is the waiting area where valid but unconfirmed transactions sit on network nodes until a miner or validator includes them in a block.","onchain",1],["mev","MEV (maximal extractable value)","MEV, or maximal extractable value, is the profit that block producers and specialised bots can make by choosing, inserting or reordering transactions inside a block, often at the expense of ordinary users.","defi",1],["mica","MiCA (EU Markets in Crypto-Assets)","MiCA (Markets in Crypto-Assets) is the European Union regulation that sets common rules for crypto-asset issuers, stablecoins and crypto service providers across all EU member states.","regulation",1],["multisig-wallet","Multisig wallet","A multisig wallet is a crypto wallet that needs signatures from several separate keys, such as 2 of 3, before any transaction can be sent, so no single lost or stolen key can move the funds.","wallets-security",1],["nft","NFT (non-fungible token)","An NFT, or non-fungible token, is a unique token on a blockchain that records ownership of a specific item, such as a digital artwork, collectible, game item or membership pass.","defi",1],["no-kyc-exchange","No-KYC exchange","A no-KYC exchange is a platform that lets you trade crypto without verifying your identity, either fully or up to certain withdrawal limits.","regulation",1],["node","Node","A node is a computer running a blockchain's software that stores, checks and relays transactions and blocks, helping keep the network decentralized and honest.","onchain",1],["non-custodial-wallet","Non-custodial wallet (self-custody wallet)","A non-custodial wallet is a crypto wallet where you alone hold the private keys or seed phrase, so no exchange or company can move, freeze or recover your funds for you.","wallets-security",1],["oco-order","OCO order (one-cancels-the-other)","An OCO (one-cancels-the-other) order pairs two orders, typically a take-profit and a stop-loss, so that when one of them executes, the other is automatically cancelled.","trading",1],["on-chain-analysis","On-chain analysis","On-chain analysis is the study of public blockchain data, such as transactions, wallet balances and exchange flows, to understand how a network is used and how holders behave.","onchain",1],["open-interest","Open interest","Open interest is the total number or value of derivatives contracts, such as futures or options, that are currently open and not yet closed or settled.","derivatives",1],["order-book","Order book","An order book is the live list of all open buy orders (bids) and sell orders (asks) for a trading pair, sorted by price, showing how much people are willing to trade at each level.","trading",1],["p2p-trading","P2P (C2C) trading","P2P (C2C) trading is buying or selling crypto directly with another user, paying in local money through bank transfer or payment apps while the platform holds the crypto in escrow.","exchange-features",1],["perp-dex","Perp DEX (on-chain perpetuals)","A perp DEX is a decentralized exchange for perpetual futures, letting you trade with leverage from your own wallet while margin, positions and settlement are handled on-chain or on a dedicated chain.","defi",1],["perpetual-futures","Perpetual futures (perps)","Perpetual futures (perps) are futures contracts with no expiry date that use a periodic funding rate to keep their price close to the underlying spot price.","derivatives",1],["phishing","Phishing","Phishing is a scam where attackers impersonate a trusted exchange, wallet or person to trick you into revealing login details or a seed phrase, or into signing a transaction that hands over your funds.","wallets-security",1],["pig-butchering-scam","Pig-butchering scam","A pig-butchering scam is a long-con fraud where a stranger builds trust over weeks, often as a friend or romantic interest, then steers you into a fake crypto investment platform and takes everything you deposit.","wallets-security",1],["portfolio-margin","Portfolio margin","Portfolio margin is a margin system that sets your collateral requirement based on the combined risk of all your positions, so hedged positions need less margin than they would separately.","derivatives",1],["position-sizing","Position sizing","Position sizing is deciding how much to put into a single trade so that, if your stop-loss is hit, you lose only a planned share of your account.","trading",1],["post-only-order","Post-only order","A post-only order is a limit order that is only allowed to add liquidity to the order book; if it would fill immediately against an existing order, the exchange cancels or adjusts it instead.","trading",1],["private-key","Private key","A private key is a secret number that proves ownership of a crypto address and is used to sign transactions, so whoever holds it can spend the coins at that address.","wallets-security",1],["proof-of-reserves","Proof of reserves","Proof of reserves is a report in which a crypto exchange shows that the assets it holds in wallets it controls are at least equal to the balances it owes its customers.","wallets-security",1],["proof-of-stake","Proof of stake (PoS)","Proof of stake (PoS) is a consensus mechanism in which validators lock up the network's coins as collateral to propose and confirm blocks, earning rewards for honest work and losing part of their stake for breaking the rules.","basics",1],["proof-of-work","Proof of work (PoW)","Proof of work (PoW) is a consensus mechanism in which miners use computing power to solve a puzzle, and the first to find a valid answer earns the right to add the next block and collect the reward.","basics",1],["public-key","Public key","A public key is the shareable half of a crypto key pair, calculated from the private key, that lets the network verify your signatures and from which your wallet address is derived.","wallets-security",1],["real-world-assets","Real-world assets (RWA)","Real-world assets (RWA) are traditional assets such as bonds, gold, real estate, private credit or stocks represented as tokens on a blockchain.","tokenized-assets",1],["reduce-only-order","Reduce-only order","A reduce-only order is a futures order setting that can only shrink or close an existing position and will never open a new one or increase it.","derivatives",1],["referral-code","Referral code (fee rebate)","A referral code is a code you enter when signing up to an exchange that links your account to a referrer and can give you a discount or rebate on trading fees.","exchange-features",1],["restaking","Restaking","Restaking is reusing already staked ETH, or a liquid staking token, to also secure additional services, earning extra rewards in exchange for extra slashing and smart contract risk.","defi",1],["risk-reward-ratio","Risk-reward ratio","The risk-reward ratio compares how much you could lose on a trade, up to your stop-loss, with how much you could gain, up to your take-profit target.","trading",1],["rug-pull","Rug pull","A rug pull is a scam where the creators of a crypto project suddenly drain its liquidity, dump their tokens or abandon it after attracting buyers, leaving the token close to worthless.","wallets-security",1],["satoshi","Satoshi (sats)","A satoshi (sat) is the smallest unit of Bitcoin, equal to 0.00000001 BTC, so one bitcoin contains 100,000,000 satoshis.","basics",1],["seed-phrase","Seed phrase (recovery phrase)","A seed phrase is a list of usually 12 or 24 ordinary words that encodes the master key of a crypto wallet, so anyone who has the words can restore the wallet and spend all of its funds.","wallets-security",1],["short-selling","Short selling","Short selling is a way to profit from a falling price by selling an asset you have borrowed, or opening a short contract, and buying it back later at a lower price.","derivatives",1],["short-squeeze","Short squeeze","A short squeeze is a rapid price rise that forces short sellers to buy back their positions, through stop-losses or liquidation, which pushes the price even higher.","derivatives",1],["slippage","Slippage","Slippage is the difference between the price you expect when you place a trade and the average price at which the trade actually fills, usually caused by thin liquidity or fast-moving markets.","trading",1],["smart-contract","Smart contract","A smart contract is a program stored on a blockchain that runs automatically when its conditions are met, letting people trade, lend or issue tokens without a middleman.","basics",1],["spot-bitcoin-etf","Spot bitcoin ETF","A spot bitcoin ETF is an exchange-traded fund that holds actual bitcoin and lets investors gain exposure to its price through a regular brokerage account.","regulation",1],["spot-trading","Spot trading","Spot trading is buying or selling a cryptocurrency for immediate delivery at the current market price, so you actually own the coins once the trade is filled.","trading",1],["stablecoin","Stablecoin","A stablecoin is a cryptocurrency designed to keep a steady value, usually 1 US dollar, by being backed by reserves such as cash and treasury bills, by crypto collateral, or by other mechanisms.","stablecoins",1],["staking","Staking","Staking is locking up coins of a proof-of-stake blockchain to help validate transactions and secure the network, in return for staking rewards paid in that coin.","defi",1],["stock-perpetuals","Stock perpetuals","Stock perpetuals are perpetual futures contracts that track the price of a share or stock index, letting you go long or short with leverage without owning the stock.","tokenized-assets",1],["stop-limit-order","Stop-limit order","A stop-limit order combines a stop price and a limit price: when the market reaches the stop price, a limit order is placed at your limit price, so it only fills at that price or better.","trading",1],["stop-loss","Stop-loss order","A stop-loss order is an order that automatically closes your position when the price reaches a level you set, limiting how much you can lose on a trade.","trading",1],["sub-account","Sub-account","A sub-account is a separate account created under your main exchange account, with its own balances and positions, used to separate strategies, bots or team members.","exchange-features",1],["support-and-resistance","Support and resistance","Support and resistance are price zones where an asset has repeatedly stopped falling (support) or stopped rising (resistance), because buying or selling interest tends to cluster there.","trading",1],["synthetic-dollar","Synthetic dollar (delta-neutral stablecoin)","A synthetic dollar is a dollar-pegged token backed by a crypto asset plus an equal short futures position, so price moves cancel out and the combined value stays near 1 USD.","stablecoins",1],["take-profit","Take-profit order","A take-profit order is an order that automatically closes all or part of your position when the price reaches a target level, locking in gains without you having to watch the market.","trading",1],["time-in-force","Time in force (GTC, IOC, FOK)","Time in force is an order setting that controls how long an order stays active and how it handles partial fills, with common options GTC (good till cancelled), IOC (immediate or cancel) and FOK (fill or kill).","trading",1],["token-approval","Token approval (allowance)","A token approval is a permission you sign in your wallet that lets a smart contract spend a set amount of a specific token from your address, often needed before swapping or depositing in DeFi.","wallets-security",1],["token-burn","Token burn","A token burn is the permanent removal of tokens from circulation by sending them to an address that nobody can access or by destroying them through a smart contract.","basics",1],["token-listing","Token listing","A token listing is when an exchange adds a coin to its markets, letting users deposit, trade and withdraw it on that platform.","exchange-features",1],["token-unlock","Token unlock","A token unlock is a scheduled event when previously locked tokens, usually held by the team, investors or a treasury, become free to transfer and sell, increasing circulating supply.","basics",1],["tokenized-gold","Tokenized gold","Tokenized gold is a blockchain token backed by physical gold held in a vault, where each token represents a set amount of gold, often one fine troy ounce.","tokenized-assets",1],["tokenized-stocks","Tokenized stocks","Tokenized stocks are blockchain tokens designed to track the price of a company's shares, usually backed one to one by real shares held by a custodian.","tokenized-assets",1],["tokenized-treasuries","Tokenized treasuries","Tokenized treasuries are blockchain tokens that represent shares in a fund or vehicle holding short-term government bonds such as US Treasury bills, passing their yield to holders.","tokenized-assets",1],["tokenomics","Tokenomics","Tokenomics is the economic design of a cryptocurrency, covering how many tokens exist, who received them, how new tokens are released and what the token is actually used for.","basics",1],["total-value-locked","Total value locked (TVL)","Total value locked (TVL) is the total market value of crypto deposited in a DeFi protocol or blockchain's smart contracts, used as a rough measure of its size and usage.","defi",1],["trading-pair","Trading pair","A trading pair is two assets that can be exchanged for each other on a market, such as BTC/USDT, where the first is the base asset you buy or sell and the second is the quote asset used to price it.","trading",1],["trading-volume","Trading volume","Trading volume is the total amount of an asset traded over a set period, usually shown as the 24-hour volume in coins or in USD value.","trading",1],["trailing-stop","Trailing stop","A trailing stop is a stop order that automatically follows the price at a set distance as it moves in your favour, then triggers if the price reverses by that distance.","trading",1],["transaction-hash","Transaction hash (TxID)","A transaction hash, or TxID, is the unique identifier of a blockchain transaction, which you can paste into a block explorer to see its status, amount, addresses and confirmations.","wallets-security",1],["travel-rule","Travel rule","The travel rule is an anti-money laundering requirement that makes crypto service providers share sender and recipient information when they transfer crypto for customers.","regulation",1],["two-factor-authentication","Two-factor authentication (2FA)","Two-factor authentication (2FA) is a login and approval method that asks for a second proof, such as a code from an authenticator app or a security key, in addition to your password.","wallets-security",1],["unified-trading-account","Unified trading account (UTA)","A unified trading account (UTA) is an exchange account mode that lets you trade spot, margin, futures and sometimes options from one balance, with assets shared as collateral.","exchange-features",1],["unrealized-pnl","Unrealized PnL","Unrealized PnL is the profit or loss on a position that is still open, calculated from your entry price and the current price, and it only becomes real when you close the position.","derivatives",1],["usdc","USDC","USDC is a US dollar stablecoin issued by Circle, designed to stay at 1 dollar and backed by cash and short-term US government securities, with monthly reserve attestations.","stablecoins",1],["usdt","USDT (Tether)","USDT, also called Tether, is the largest US dollar stablecoin, issued by Tether, designed to stay at 1 dollar and backed by reserves the company reports in regular attestations.","stablecoins",1],["usdt-margined-futures","USDT-margined (linear) futures","USDT-margined (linear) futures are futures contracts where margin, profit and loss are all in the stablecoin USDT, so results move in a straight line with the price.","derivatives",1],["validator","Validator","A validator is a participant in a proof-of-stake blockchain that locks up coins as collateral and runs software to propose new blocks and vote on whether other blocks are valid.","basics",1],["vasp","VASP (virtual asset service provider)","A VASP (virtual asset service provider) is a business that exchanges, transfers, holds or manages crypto for customers and must follow anti-money laundering rules where it operates.","regulation",1],["vip-tier","VIP fee tier","A VIP fee tier is an exchange level that gives lower trading fees and extra benefits to users who trade high volume or hold large balances.","exchange-features",1],["volatility","Volatility","Volatility is a measure of how much and how quickly an asset's price moves up and down over a given period, and higher volatility means larger, faster swings.","basics",1],["wallet-address","Wallet address","A wallet address is a string of letters and numbers that identifies where crypto can be sent on a specific blockchain, similar to an account number you can share publicly.","wallets-security",1],["wash-trading","Wash trading","Wash trading is when the same person or group buys and sells an asset to themselves to create fake trading volume and a false impression of demand.","trading",1],["whale","Whale","A whale is an individual or entity that holds or trades such a large amount of a cryptocurrency that their moves can noticeably affect its price or liquidity.","trading",1],["withdrawal-fee","Withdrawal fee","A withdrawal fee is the amount an exchange charges when you send crypto from your account to an external address, usually to cover the blockchain network fee.","exchange-features",1],["withdrawal-whitelist","Withdrawal whitelist","A withdrawal whitelist is an exchange security setting that only allows withdrawals to addresses you have saved and approved in advance, blocking transfers to any new address.","wallets-security",1],["wrapped-token","Wrapped token","A wrapped token is a token on one blockchain that represents another asset one-to-one, such as WBTC representing bitcoin on Ethereum, backed by the original asset held by a custodian or smart contract.","defi",1],["yield-farming","Yield farming","Yield farming is the practice of moving crypto into DeFi protocols, such as liquidity pools or lending markets, to earn trading fees, interest and extra token rewards.","defi",1]]});
